function l29CsvRead(text){
 requireValue(typeof text==='string'&&text.length<=2000000,'Use a CSV file smaller than 2 MB.');const rows=[],row=[];let value='',quoted=false,afterQuote=false;
 for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){value+='"';i++;}else if(c==='"'){quoted=false;afterQuote=true;}else value+=c;continue;}if(c==='"'){requireValue(value===''&&!afterQuote,'Unexpected quotation mark in CSV.');quoted=true;continue;}if(c===','||c==='\n'||c==='\r'){row.push(value);value='';afterQuote=false;if(c!==','){if(c==='\r'&&text[i+1]==='\n')i++;if(row.some(v=>v.trim()!==''))rows.push(row.splice(0));else row.splice(0);}continue;}requireValue(!afterQuote||/\s/.test(c),'Unexpected text after a quoted CSV field.');if(!afterQuote)value+=c;}
 requireValue(!quoted,'The CSV contains an unfinished quoted field.');if(value||row.length){row.push(value);if(row.some(v=>v.trim()!==''))rows.push(row);}requireValue(rows.length>1,'Include column headers and at least one transaction row.');requireValue(rows.length<=1001,'Import up to 1,000 rows at a time.');const headers=rows.shift().map((h,i)=>l29Text(i===0?h.replace(/^\uFEFF/,''):h).toUpperCase());requireValue(new Set(headers).size===headers.length,'CSV column names must be unique.');const missing=CS_LOSS_REFERENCE.columns.map(c=>c[0].toUpperCase()).filter(h=>!headers.includes(h));requireValue(!missing.length,'Missing source columns: '+missing.join(', '));return rows.map((r,i)=>{requireValue(r.length===headers.length,'Row '+(i+2)+' has '+r.length+' values; expected '+headers.length+'.');return {row:i+2,raw:Object.fromEntries(headers.map((h,j)=>[h,l29Text(r[j])]))};});
}
function l29SourceDate(value){const s=l29Text(value);if(!s)return '';let d=s;if(/^\d{4,6}(?:\.0+)?$/.test(s)){const n=Number(s);requireValue(n>=1&&n<=100000,'Excel date serial is outside the supported range.');d=new Date(Date.UTC(1899,11,30)+n*86400000).toISOString().slice(0,10);}else if(/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(s)){const [day,month,year]=s.split('/');d=year+'-'+month.padStart(2,'0')+'-'+day.padStart(2,'0');}requireValue(l29KnownDate(d),'Use ISO dates, day/month/year dates or Excel day serials.');return d;}
function l29ImportRow(item,batchId){
 const raw=item.raw,data=l29Blank(''),errors=[],warnings=[],parseDate=(key)=>{try{return l29SourceDate(raw[key])}catch(err){errors.push(key+': '+err.message);return ''}},monthNames=['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'],monthName=monthNames.indexOf((raw.Month||raw.MONTH||'').slice(0,3).toLowerCase())+1,monthNumber=/^\d+$/.test(raw['MONTH NUMBER'])?Number(raw['MONTH NUMBER']):monthName,year=raw.YEAR;
 data.accountName=raw.ACCT_NAME;data.lossGroup=raw['LOSS GROUP'];data.transactionParticulars=raw.TRAN_PARTICULAR;data.title=(raw['LOSS GROUP']||raw.ACCT_NAME||'Imported loss')+' · '+raw.TRAN_PARTICULAR.slice(0,95);data.region=raw['REGIONAL BANK'];data.directorate=raw.DIRECTORATE;data.date=parseDate('DATE OF OCCURRENCE');data.recognizedOn=parseDate('DATE OF RECOGNITION');data.discoveredOn='';data.rootCause=raw['ROOT CAUSE ANALYSIS'];data.rootCauseStatus=data.rootCause.length>=10?'Confirmed':'Under investigation';data.recoveryNote=raw['RECOVERY DATA'];data.sourceRef=batchId+' / source row '+item.row;
 const currency=l29Text(raw['CURRENCY OF LOSS']).toUpperCase();data.currency=({'NAIRA':'NGN','NIGERIAN NAIRA':'NGN','₦':'NGN','US DOLLAR':'USD','DOLLAR':'USD','EURO':'EUR','POUND STERLING':'GBP','RAND':'ZAR'})[currency]||currency;if(!CS_LOSS_REFERENCE.currencies.includes(data.currency))errors.push('Map the original currency to NGN, USD, EUR, GBP or ZAR.');
 const amount=l29Text(raw.AMOUNT);data.gross=/^\d{1,3}(,\d{3})+(\.\d{1,2})?$/.test(amount)?amount.replace(/,/g,''):amount;try{const n=l29Minor(data.gross);if(n===0)warnings.push('Zero source amount: confirm the event classification in the draft; it has not been inferred as a near miss.');}catch(err){errors.push('Amount: '+err.message);}if(!data.date||data.date>S.asOf)errors.push('Occurrence date is missing or after the snapshot.');if(data.type==='Actual loss'&&(!data.recognizedOn||data.recognizedOn>S.asOf||data.recognizedOn<data.date))errors.push('Recognition must be between occurrence and the snapshot.');
 if(/^\d{4}$/.test(year)&&monthNumber>=1&&monthNumber<=12)data.reportingPeriod=year+'-'+String(monthNumber).padStart(2,'0');else{data.reportingPeriod='';errors.push('YEAR and Month Number must define one reporting period.');}if(data.reportingPeriod>S.asOf.slice(0,7))errors.push('Reporting period is after the snapshot.');if(monthName&&monthNumber!==monthName)warnings.push('Month label conflicts with Month Number; verify the reporting period.');
 const quarter=Math.ceil(monthNumber/3),sourceQuarter=l29Text(raw.QUARTER).toUpperCase();if(sourceQuarter&&sourceQuarter!=='Q'+quarter)warnings.push('Quarter label conflicts with reporting period; the draft derives Q'+quarter+'.');if(raw['QTR NUMBER']&&Number(raw['QTR NUMBER'])!==quarter)warnings.push('QTR NUMBER conflicts with reporting period; the draft derives '+quarter+'.');if(data.recognizedOn&&data.reportingPeriod!==data.recognizedOn.slice(0,7))warnings.push('Reporting period differs from recognition month; explain this before submission.');
 const recoveredOn=parseDate('DATE OF RECOVERY');if(recoveredOn)data.recoveryNote+=(data.recoveryNote?'\n':'')+'Source recovery date: '+recoveredOn;if(data.recoveryNote)warnings.push('Recovery narrative retained as context. No received amount is verified by this import.');if(!data.accountName||!data.lossGroup||!data.transactionParticulars)errors.push('Account name, loss group and transaction particulars are required.');
 const match=ORG.filter(n=>[n.id,n.name,orgName(n.id)].some(v=>l29Text(v).toLowerCase()===l29Text(raw.BRANCH).toLowerCase()));if(match.length===1)data.orgScopeId=match[0].id;
 return {row:item.row,raw,data,errors,warnings,include:true,duplicateReason:'',status:'Pending mapping'};
}
function l29RefreshImport(batch){const seen=new Map();for(const r of batch.rows){r.mappingError=!r.data.orgScopeId||!orgNode(r.data.orgScopeId)?'Map the source branch to an organizational location.':!l29InScope(r.data)?'Mapped location is outside the selected scope.':!l29Permission('edit',r.data).allowed?'The selected identity cannot prepare losses in the mapped location.':'';r.duplicates=l29Duplicates(r.data);const fp=l29Fingerprint(r.data);if(seen.has(fp))r.duplicates.push('source row '+seen.get(fp));else seen.set(fp,r.row);r.status=r.errors.length||r.mappingError?'Needs correction':r.duplicates.length&&!r.data.duplicateReason?'Duplicate candidate':'Ready for draft';}return batch;}
function l29StageImport(csvText){lossInit();const id=uid('LIMP'),batch={id,createdBy:l29Actor().id,createdAt:l29Clock(),status:'Preview',rows:l29CsvRead(csvText).map(item=>l29ImportRow(item,id))};S.lossRegister.imports.unshift(batch);l29RefreshImport(batch);save();go('loss-import?id='+id);return batch;}
function l29ImportBatch(id){const batch=S.lossRegister.imports.find(b=>b.id===id);requireValue(batch,'The import preview is unavailable.');requireValue(batch.createdBy===l29Actor().id,'Switch to the import preparer to continue this preview.');requireValue(batch.status==='Preview','This import has already been committed.');return l29RefreshImport(batch);}
function l29MapImport(id,mappings){const b=l29ImportBatch(id);for(const r of b.rows){const location=mappings[r.raw.BRANCH];if(location!==undefined){requireValue(!location||!!orgNode(location),'Choose a known organizational location.');r.data.orgScopeId=location;}}l29RefreshImport(b);save();return b;}
function l29ResolveImportDuplicate(id,row,reference,reason){const b=l29ImportBatch(id),r=b.rows.find(r=>r.row===Number(row));requireValue(r,'This source row is unavailable.');requireValue(l29Text(reference).length>=3&&l29Text(reason).length>=20,'Provide a distinct transaction reference and a substantive explanation.');requireValue(!S.losses.some(l=>l29Text(l.transactionReference).toLowerCase()===l29Text(reference).toLowerCase())&&!b.rows.some(other=>other!==r&&l29Text(other.data.transactionReference).toLowerCase()===l29Text(reference).toLowerCase()),'Use a transaction reference that does not already identify another event.');r.data.transactionReference=l29Text(reference);r.data.duplicateReason=l29Text(reason);l29RefreshImport(b);save();return r;}
function l29CommitImport(id,rowNumbers){const b=l29ImportBatch(id),selected=new Set(rowNumbers.map(Number)),rows=b.rows.filter(r=>selected.has(r.row));requireValue(rows.length,'Select at least one ready row.');requireValue(rows.every(r=>r.status==='Ready for draft'),'Resolve mapping, source errors and duplicate candidates before creating drafts.');const created=[];for(const r of rows){l29Require('edit',r.data);const draft={id:uid('LDF'),kind:'new',data:clone(r.data),step:1,createdBy:l29Actor().id,createdAt:l29Clock(),origin:'Imported worksheet draft',importId:b.id,sourceRow:r.row,sourceColumns:clone(r.raw)};S.lossRegister.drafts[draft.id]=draft;r.draftId=draft.id;r.status='Draft created';created.push(draft.id);}b.status='Committed';b.committedAt=l29Clock();b.createdDrafts=created;b.excludedRows=b.rows.filter(r=>!selected.has(r.row)).map(r=>({row:r.row,status:r.status}));audit('Imported '+created.length+' loss drafts; '+b.excludedRows.length+' rows excluded. No financial losses booked.',b.id,l29Actor().name);save();return created;}
function l29ImportView(){lossInit();const requested=current.params.get('id'),b=requested&&S.lossRegister.imports.find(b=>b.id===requested);if(requested&&!b)return uxUnavailable('This loss import preview is unavailable.','loss-import');const base=header('Import loss worksheet','Review the source columns, map branches and resolve repeated transactions before creating drafts.',`${link('Back to register','losses','quiet')}${btn('Download column template','l29-template','','quiet')}`)+l29ActorBar()+l29Nav();if(b&&b.createdBy!==l29Actor().id)return base+notice('Switch to '+(recUser(b.createdBy)?.name||'the import preparer')+' to review this import.','mini');
 if(b?.status==='Committed')return base+panel('Import completed',b.createdDrafts.length+' drafts created · '+b.excludedRows.length+' rows excluded · no financial totals changed.',table(['Source row','Outcome',''],b.rows.map(r=>({cells:[e(r.row),e(r.draftId?'Draft created':r.status),r.draftId?link('Complete draft','loss-intake?id='+r.draftId,'quiet small'):'Excluded from this import']}))))+link('Start another import','loss-import','quiet');
 if(!b){const previews=S.lossRegister.imports.filter(b=>b.createdBy===l29Actor().id);return base+panel('Load a CSV copy of the loss worksheet','Save Sheet1 as CSV with its original 18 column headers. Dates may be ISO, day/month/year, or Excel day serials.',`<form data-l29-form="import"><label>Choose CSV file<input type="file" accept=".csv,text/csv" data-l29-csv></label>${area('csv','Or paste CSV including the header row','','required rows="9" spellcheck="false"')}<div id="l29-error" class="form-error" role="alert" hidden></div><button type="submit" class="primary">Review import</button></form><p class="muted">Maximum 1,000 rows / 2 MB. An import never creates recovery receipts or accepted loss records. The original source columns remain attached to each generated draft.</p>`)+(previews.length?panel('Your import history','Resume a preview or inspect its recorded outcome.',table(['Import','Created','State',''],previews.map(p=>({cells:[e(p.id),e(p.createdAt.slice(0,10)),e(p.status),link('Open','loss-import?id='+p.id,'quiet small')]})))):'');}
 l29RefreshImport(b);const branches=[...new Set(b.rows.map(r=>r.raw.BRANCH))],ready=b.rows.filter(r=>r.status==='Ready for draft').length;return base+notice(`${b.rows.length} source rows · ${ready} ready for draft · ${b.rows.filter(r=>r.status==='Duplicate candidate').length} duplicate candidates. Only selected ready rows will be imported.`,'mini')+panel('1. Map source branches','Choose the exact location for each source branch. Mappings are never inferred from the reporting month.',`<form data-l29-form="import-map" data-id="${e(b.id)}"><div class="l29-field-grid">${branches.map((name,i)=>select('branch_'+i,e(name||'Blank source branch'),[['','Choose location'],...l29Locations()],b.rows.find(r=>r.raw.BRANCH===name).data.orgScopeId)).join('')}</div><button type="submit" class="primary">Apply branch mapping</button></form>`)+panel('2. Review rows','Repeated transaction details are compared across reporting periods. A repeated month label does not establish a separate loss.',`<div id="l29-error" class="form-error" role="alert" hidden></div><form data-l29-form="import-commit" data-id="${e(b.id)}">${table(['Include','Source row / event','Period / occurrence / recognition','Location','Amount','Review result',''],b.rows.map(r=>({cells:[`<input type="checkbox" name="row_${r.row}" aria-label="Include source row ${r.row}" ${r.status==='Ready for draft'?'checked':'disabled'}>`,`${r.row}<small class="cell-sub">${e(r.data.title)}</small>`,`${e(r.data.reportingPeriod)}<small class="cell-sub">${e(r.data.date)} / ${e(r.data.recognizedOn)}</small>`,e(r.data.orgScopeId?orgName(r.data.orgScopeId):r.raw.BRANCH||'Unmapped'),e(r.data.currency+' '+r.data.gross),`${pill(r.status)}<small class="cell-sub">${[...r.errors,r.mappingError,...r.warnings,r.duplicates.length?'Matches '+r.duplicates.join(', '):''].filter(Boolean).map(e).join('<br>')}</small>`,r.duplicates.length?btn('Distinct event?','l29-import-distinct',`data-id="${e(b.id)}" data-row="${r.row}"`,'quiet small'):'' ]})))}<div class="l29-footer"><p>Rows with source errors stay excluded. Correct the CSV and start another preview, or leave them out.</p><button type="submit" class="primary" ${ready?'':'disabled'}>Create selected drafts</button></div></form>`);
}
actions['l29-template']=()=>exportCSV('loss-database-import-template.csv',CS_LOSS_REFERENCE.columns.map(c=>c[0]),[]);
actions['l29-import-distinct']=el=>{const b=l29ImportBatch(el.dataset.id),r=b.rows.find(r=>r.row===Number(el.dataset.row));openDialog('Confirm a distinct loss event','Use this only when the repeated details represent a separate underlying transaction.',`${input('reference','Unique transaction / journal reference',r.data.transactionReference,'text','required minlength="3"')}${area('reason','Why is this a different event?',r.data.duplicateReason,'required minlength="20"')}`,'Record distinction',form=>{const x=values(form);l29ResolveImportDuplicate(b.id,r.row,x.reference,x.reason);render();});};
document.addEventListener('change',async ev=>{if(!ev.target.matches?.('[data-l29-csv]'))return;try{const file=ev.target.files?.[0];if(!file)return;requireValue(file.size<=2000000,'Use a CSV file smaller than 2 MB.');const text=await file.text(),field=$('textarea[name="csv"]');requireValue(field,'The import editor is no longer open.');field.value=text;toast('CSV loaded. Review the import to validate its rows.');}catch(err){l29DialogError(err);}});
document.addEventListener('submit',ev=>{const form=ev.target,kind=form.dataset?.l29Form;if(!['import','import-map','import-commit'].includes(kind))return;ev.preventDefault();try{const x=values(form);if(kind==='import'){l29StageImport(x.csv);return;}if(kind==='import-map'){const b=l29ImportBatch(form.dataset.id),names=[...new Set(b.rows.map(r=>r.raw.BRANCH))];l29MapImport(b.id,Object.fromEntries(names.map((name,i)=>[name,x['branch_'+i]||''])));render();return;}const b=l29ImportBatch(form.dataset.id),rows=b.rows.filter(r=>x['row_'+r.row]).map(r=>r.row);l29CommitImport(b.id,rows);render();toast('Loss drafts created. Complete and submit each draft for review.');}catch(err){l29DialogError(err);}});
window.CS_JOURNEYS['loss-import']=l29ImportView;

// Old links and command entry points resume the same reviewed loss journey.
function l29MigrateSetupDraft(id){lossInit();if(S.lossRegister.drafts[id])return S.lossRegister.drafts[id];const old=S.journeyDrafts?.[id];if(old?.kind!=='loss')return null;const risk=S.risks.find(r=>r.id===old.data.risk),data={...l29Blank(risk?.orgScopeId||old.data.orgScopeId||''),...old.data,transactionParticulars:old.data.note||'',currency:'NGN',owner:risk?.owner||l29Actor().name};const d={id,kind:'new',data,step:1,createdBy:recUserId(risk?.owner)||l29Actor().id,createdAt:l29Clock(),origin:'Resumed earlier loss setup'};S.lossRegister.drafts[id]=d;delete S.journeyDrafts[id];save();return d;}
const l29OldStartOperation=jStartOperation;jStartOperation=function(kind,extra={}){return kind==='loss'?l29NewDraft(extra.risk||''):l29OldStartOperation(kind,extra);};
const l29OldSubmitOperation=jSubmitOperation;jSubmitOperation=function(){const id=current.params.get('draft'),old=S.journeyDrafts?.[id],migrated=S.lossRegister?.drafts?.[id];if(old?.kind==='loss'||migrated){const d=l29MigrateSetupDraft(id);go('loss-intake?id='+d.id);toast('Complete the source-aligned capture and independent review.');return d;}return l29OldSubmitOperation();};
const l29OldSetupView=window.CS_JOURNEYS.setup;window.CS_JOURNEYS.setup=function(){const id=current.params.get('draft'),d=l29MigrateSetupDraft(id);if(d){current.params.set('id',d.id);return l29IntakeView();}return l29OldSetupView();};
